discovery.kubernetes "pod" {
  role = "pod"
  selectors {
    role  = "pod"
    field = "spec.nodeName=" + sys.env("NODE_NAME")
  }
}

discovery.relabel "pod_logs" {
  targets = discovery.kubernetes.pod.targets

  rule {
    source_labels = ["__meta_kubernetes_namespace"]
    action        = "replace"
    target_label  = "namespace"
  }

  rule {
    source_labels = ["__meta_kubernetes_pod_name"]
    action        = "replace"
    target_label  = "pod"
  }

  rule {
    source_labels = ["__meta_kubernetes_pod_container_name"]
    action        = "replace"
    target_label  = "container"
  }

  rule {
    source_labels = ["__meta_kubernetes_namespace", "__meta_kubernetes_pod_container_name"]
    action        = "replace"
    target_label  = "job"
    separator     = "/"
    replacement   = "$1"
  }

  rule {
    source_labels = ["__meta_kubernetes_pod_uid", "__meta_kubernetes_pod_container_name"]
    action        = "replace"
    target_label  = "__path__"
    separator     = "/"
    replacement   = "/var/log/pods/*$1/*.log"
  }
}

loki.source.kubernetes "pod_logs" {
  targets    = discovery.relabel.pod_logs.output
  forward_to = [loki.process.pod_logs.receiver]
}

loki.source.kubernetes_events "events" {
  forward_to = [loki.process.kubernetes_events.receiver]
}

// Talos kernel/service logs forwarded over TCP syslog from each node's machined.
// Receives Talos json_lines format; syslog parse is best-effort — raw JSON lines
// are stored in Loki and can be parsed at query time with | json.
// Requires machine.logging.destinations configured via talosctl apply-config.
loki.source.syslog "talos" {
  listener {
    address  = "0.0.0.0:6514"
    protocol = "tcp"
    labels   = {
      job     = "talos/kernel",
      cluster = "homelab-cluster",
      node    = sys.env("NODE_NAME"),
    }
  }
  forward_to = [loki.write.local.receiver]
}

loki.process "pod_logs" {
  stage.static_labels {
    values = {
      cluster = "homelab-cluster",
    }
  }

  forward_to = [loki.write.local.receiver]
}

loki.process "kubernetes_events" {
  stage.static_labels {
    values = {
      cluster = "homelab-cluster",
      job     = "kubernetes/events",
    }
  }

  forward_to = [loki.write.local.receiver]
}

loki.write "local" {
  endpoint {
    url = "http://loki-gateway.observability.svc.cluster.local/loki/api/v1/push"
  }
}

faro.receiver "main" {
  server {
    listen_address = "0.0.0.0:12347"
  }

  output {
    logs   = [loki.write.main.receiver]
    traces = [otelcol.processor.batch.main.input]
  }
}

loki.write "main" {
  endpoint {
    url = "http://loki-gateway.observability.svc.cluster.local/loki/api/v1/push"
  }
}

otelcol.receiver.otlp "main" {
  grpc {
    endpoint = "0.0.0.0:4317"
  }

  http {
    endpoint = "0.0.0.0:4318"
  }

  output {
    traces = [otelcol.processor.batch.main.input]
    logs   = [otelcol.processor.attributes.loki_labels.input]
    metrics = [otelcol.processor.batch.metrics.input]
  }
}

otelcol.processor.batch "metrics" {
  output {
    metrics = [otelcol.exporter.prometheus.prometheus.input]
  }
}

otelcol.exporter.prometheus "prometheus" {
  forward_to = [prometheus.remote_write.prometheus.receiver]
}

prometheus.remote_write "prometheus" {
  endpoint {
    url = "http://vmsingle-vmsingle.observability.svc.cluster.local:8429/api/v1/write"
  }
}

otelcol.processor.attributes "loki_labels" {
  action {
    key = "loki.resource.labels"
    action = "insert"
    value = "service.name, service.namespace, deployment.environment"
  }

  action {
    key = "loki.attribute.labels"
    action = "insert"
    value = "event.domain, event.name"
  }

  output {
    logs = [otelcol.exporter.loki.main.input]
  }
}

otelcol.exporter.loki "main" {
  forward_to = [loki.write.main.receiver]
}

otelcol.processor.batch "main" {
  output {
    traces = [otelcol.exporter.otlp.tempo.input]
  }
}

otelcol.exporter.otlp "tempo" {
  client {
    endpoint = "tempo.observability.svc.cluster.local:4317"
    tls {
      insecure = true
    }
  }
}
